/**
 * Renders `supabase/seed/seed.sql` from the engine's canonical data.
 *
 * Exported as a function so tests can assert the committed file matches its generator —
 * a generated file that drifts from its source is a lie that only shows up after a deploy.
 *
 * Single source of truth: the dictionaries, industries, TLD directory and scoring profiles
 * that ship with the engine are the same records that seed the database, so an
 * unconfigured deployment and a database-backed deployment behave identically.
 *
 * Run with: npm run db:seed:generate
 */

import { INDUSTRIES } from "../src/lib/brain/dictionaries/industries";
import { PREFIX_LIBRARIES, SUFFIX_LIBRARIES, BANNED_FRAGMENTS } from "../src/lib/brain/dictionaries/words";
import { TLD_DIRECTORY } from "../src/lib/brain/tlds";
import { BRANDABLE_PROFILE_DEFINITIONS, QUALITY_PROFILES, BRANDABILITY_PROFILES } from "../src/lib/brain/scoring-profiles";
import { DEFAULT_PAGES } from "../src/lib/content/defaults";
import { FOOTER_NAV, PRIMARY_NAV } from "../src/lib/config/site";

const q = (value: string): string => `'${value.replace(/'/g, "''")}'`;
const qOrNull = (value: string | null | undefined): string => (value ? q(value) : "null");
const arr = (values: string[]): string =>
  values.length === 0 ? "'{}'::text[]" : `array[${values.map(q).join(", ")}]::text[]`;

export function buildSeedSql(): string {
  const chunks: string[] = [];
  chunks.push(`-- AUTO-GENERATED by scripts/generate-seed.ts — do not edit by hand.
-- Regenerate with: npm run db:seed:generate
-- Re-runnable: converges the database to these shipped defaults. It overwrites edits to the
-- rows it contains (menus, pages, dictionaries) — it is a seed, not a migration.

begin;

-- ---------------------------------------------------------------------------
-- Roles & permissions
-- ---------------------------------------------------------------------------
insert into public.app_roles (id, name, description, rank) values
  ('owner', 'Owner', 'Full control including role management.', 100),
  ('admin', 'Administrator', 'Manages content, naming data and settings.', 80),
  ('editor', 'Editor', 'Publishes content; cannot change security settings.', 50),
  ('viewer', 'Analyst', 'Read-only access to analytics.', 20)
on conflict (id) do nothing;

insert into public.role_permissions (role_id, permission) values
  ('owner', 'settings.write'), ('owner', 'users.manage'), ('owner', 'content.write'),
  ('owner', 'naming.write'), ('owner', 'analytics.read'), ('owner', 'monetization.write'),
  ('admin', 'settings.write'), ('admin', 'content.write'), ('admin', 'naming.write'),
  ('admin', 'analytics.read'), ('admin', 'monetization.write'),
  ('editor', 'content.write'),
  ('viewer', 'analytics.read')
on conflict do nothing;
`);

  // ---- settings -----------------------------------------------------------
  const settings: Array<[string, string, string, boolean]> = [
    ["brand", JSON.stringify({
      name: "DomainFits",
      shortName: "DomainFits",
      tagline: "Name intelligence, not name roulette.",
      description:
        "Generate brandable domain candidates with real naming logic, understand why each one scores the way it does, and check availability honestly.",
      logoMark: "DF",
      contactEmail: "hello@example.com",
      accent: "#067a68",
    }), "Brand name, tagline, logo mark and accent colour.", true],
    ["seo", JSON.stringify({
      defaultTitleSuffix: " · DomainFits",
      defaultDescription:
        "Domain name discovery, brandable naming and domain intelligence with explainable scores.",
      twitterHandle: "",
      organizationName: "DomainFits",
      allowIndexing: true,
    }), "Global SEO defaults used when a page has no override.", true],
    ["generator", JSON.stringify({
      defaultTarget: 100,
      maxTarget: 5000,
      defaultTlds: ["com", "io"],
      engineVersion: "1.0.0",
    }), "Generator defaults served to the client.", true],
    ["accounts", JSON.stringify({ enabled: true, allowAnonymousFavorites: true }),
      "Account features. Anonymous favourites always remain available.", true],
    ["analytics", JSON.stringify({ enabled: true, retentionDays: 180, saltRotationDays: 30 }),
      "First-party analytics settings.", true],
  ];

  chunks.push(`
-- ---------------------------------------------------------------------------
-- Settings
-- ---------------------------------------------------------------------------
insert into public.site_settings (key, value, description, is_public) values
${settings.map(([key, value, description, isPublic]) => `  (${q(key)}, ${q(value)}::jsonb, ${q(description)}, ${isPublic})`).join(",\n")}
on conflict (key) do nothing;
`);

  // ---- TLDs ---------------------------------------------------------------
  chunks.push(`
-- ---------------------------------------------------------------------------
-- TLD directory
-- ---------------------------------------------------------------------------
insert into public.tlds (tld, display_name, description, category, enabled, checkability, display_order, note) values
${TLD_DIRECTORY.map(
  (record) =>
    `  (${q(record.tld)}, ${q(record.displayName)}, ${q(record.description)}, ${q(record.category)}, ${record.enabled}, ${q(record.checkability)}, ${record.displayOrder}, ${qOrNull(record.note)})`,
).join(",\n")}
on conflict (tld) do nothing;
`);

  // ---- providers ----------------------------------------------------------
  chunks.push(`
-- ---------------------------------------------------------------------------
-- Availability providers (no provider is trusted until configured and tested)
-- ---------------------------------------------------------------------------
insert into public.availability_providers (id, name, kind, base_url, endpoint_template, supports_tlds, enabled, is_production, priority, timeout_ms, rate_limit_per_minute, notes) values
  ('rdap-org', 'RDAP bootstrap (rdap.org)', 'rdap', 'https://rdap.org', 'https://rdap.org/domain/{domain}', '{}'::text[], true, true, 10, 8000, 30,
   'Free redirect-based RDAP service. Follows the IANA bootstrap to the authoritative registry.'),
  ('rdap-verisign', 'Verisign RDAP (.com/.net)', 'rdap', 'https://rdap.verisign.com', 'https://rdap.verisign.com/{tld}/v1/domain/{domain}', array['com','net']::text[], true, true, 20, 6000, 60,
   'Registry-operated RDAP for .com and .net.'),
  ('test-fake', 'Local fake registry (tests only)', 'mock', null, null, '{}'::text[], false, false, 999, 2000, 1000,
   'Disabled mock used exclusively by the automated test suite. Never enable in production.')
on conflict (id) do nothing;
`);

  // ---- libraries ----------------------------------------------------------
  const libraryRows = [
    ...PREFIX_LIBRARIES.map((library, index) =>
      `  (${q(library.id)}, ${q(library.name)}, 'prefix', ${q(library.description)}, true, ${index * 10 + 10})`,
    ),
    ...SUFFIX_LIBRARIES.map((library, index) =>
      `  (${q(`suffix-${library.id}`)}, ${q(library.name)}, 'suffix', ${q(library.description)}, true, ${index * 10 + 10})`,
    ),
  ];

  // Note: prefix/suffix library ids collide ("tech" exists in both lists), so suffixes are
  // stored with a `suffix-` prefix to keep the primary key unique.
  chunks.push(`
-- ---------------------------------------------------------------------------
-- Word libraries and their terms
-- ---------------------------------------------------------------------------
insert into public.word_libraries (id, name, kind, description, enabled, display_order) values
${libraryRows.join(",\n")}
on conflict (id) do nothing;
`);

  const termRows: string[] = [];
  for (const library of PREFIX_LIBRARIES) {
    for (const word of library.words) {
      termRows.push(`  (${q(word)}, 'prefix', ${q(library.id)}, true)`);
    }
  }
  for (const library of SUFFIX_LIBRARIES) {
    for (const word of library.words) {
      termRows.push(`  (${q(word)}, 'suffix', ${q(`suffix-${library.id}`)}, true)`);
    }
  }
  for (const fragment of BANNED_FRAGMENTS) {
    termRows.push(`  (${q(fragment)}, 'excluded', null, true)`);
  }

  chunks.push(`
insert into public.dictionary_terms (word, term_type, library_id, enabled) values
${Array.from(new Set(termRows)).join(",\n")}
on conflict do nothing;
`);

  // ---- industries ---------------------------------------------------------
  chunks.push(`
-- ---------------------------------------------------------------------------
-- Industries
-- ---------------------------------------------------------------------------
insert into public.industries (id, name, slug, description, intro, semantic_weight, enabled, display_order) values
${INDUSTRIES.map(
  (industry, index) =>
    `  (${q(industry.id)}, ${q(industry.name)}, ${q(industry.slug)}, ${q(industry.description)}, ${q(
      `${industry.name} names work best when the vocabulary of the domain is recognisable at a glance. The engine draws on ${industry.relatedTerms.slice(0, 6).join(", ")} and similar terms for this industry.`,
    )}, ${industry.semanticWeight}, true, ${index * 10 + 10})`,
).join(",\n")}
on conflict (id) do nothing;
`);

  const termInserts: string[] = [];
  for (const industry of INDUSTRIES) {
    for (const keyword of industry.keywords) {
      termInserts.push(`  (${q(industry.id)}, ${q(keyword)}, 'keyword')`);
    }
    for (const term of industry.relatedTerms) {
      termInserts.push(`  (${q(industry.id)}, ${q(term)}, 'related')`);
    }
    for (const prefix of industry.prefixes) {
      termInserts.push(`  (${q(industry.id)}, ${q(prefix)}, 'prefix')`);
    }
    for (const suffix of industry.suffixes) {
      termInserts.push(`  (${q(industry.id)}, ${q(suffix)}, 'suffix')`);
    }
    for (const avoid of industry.avoid) {
      termInserts.push(`  (${q(industry.id)}, ${q(avoid)}, 'avoid')`);
    }
  }

  chunks.push(`
insert into public.industry_terms (industry_id, term, role) values
${Array.from(new Set(termInserts)).join(",\n")}
on conflict do nothing;
`);

  // ---- templates ----------------------------------------------------------
  const templateRows: string[] = [];
  for (const industry of INDUSTRIES) {
    for (const pattern of industry.patterns) {
      templateRows.push(
        `  (${q(`${industry.id}-${pattern.id}`)}, ${q(`${industry.name}: ${pattern.label}`)}, ${q(pattern.template)}, ${q(pattern.pool)}, ${q(industry.id)}, true)`,
      );
    }
  }
  chunks.push(`
insert into public.phrase_templates (id, label, template, pool, industry_id, enabled) values
${templateRows.join(",\n")}
on conflict (id) do nothing;
`);

  // ---- scoring / brandable profiles --------------------------------------
  const scoringRows = [...QUALITY_PROFILES, ...BRANDABILITY_PROFILES].map((profile) => {
    const kind = "factors" in profile && profile.id.startsWith("quality") ? "quality" : "brandability";
    const weights = Object.fromEntries(profile.factors.map((factor) => [factor.key, factor.weight]));
    return `  (${q(profile.id)}, ${profile.version}, ${q(profile.name)}, ${q(kind)}, ${q(profile.description)}, ${profile.idealLength[0]}, ${profile.idealLength[1]}, ${q(JSON.stringify(weights))}::jsonb, true)`;
  });

  chunks.push(`
-- ---------------------------------------------------------------------------
-- Scoring profiles (versioned)
-- ---------------------------------------------------------------------------
insert into public.scoring_profiles (id, version, name, kind, description, ideal_length_min, ideal_length_max, weights, is_active) values
${scoringRows.join(",\n")}
on conflict (id, version) do nothing;

insert into public.brandable_profiles (id, name, description, ideal_length_min, ideal_length_max, ideal_syllables_min, ideal_syllables_max, preferred_styles, originality_bias, enabled, display_order) values
${BRANDABLE_PROFILE_DEFINITIONS.map(
  (profile, index) =>
    `  (${q(profile.id)}, ${q(profile.name)}, ${q(profile.description)}, ${profile.idealLength[0]}, ${profile.idealLength[1]}, ${profile.idealSyllables[0]}, ${profile.idealSyllables[1]}, ${arr([])}, 0.5, true, ${index * 10 + 10})`,
).join(",\n")}
on conflict (id) do nothing;
`);

  // ---- exclusions ---------------------------------------------------------
  chunks.push(`
-- ---------------------------------------------------------------------------
-- Excluded fragments (blocked by default; admin-editable)
-- ---------------------------------------------------------------------------
insert into public.excluded_rules (pattern, match_type, reason, severity, enabled) values
${BANNED_FRAGMENTS.slice(0, 24)
  .map((fragment) => `  (${q(fragment)}, 'substring', 'Blocked vocabulary', 'block', true)`)
  .join(",\n")}
on conflict do nothing;
`);

  // ---- SEO templates ------------------------------------------------------
  chunks.push(`
-- ---------------------------------------------------------------------------
-- SEO templates
-- ---------------------------------------------------------------------------
insert into public.seo_templates (id, entity, title_template, description_template) values
  ('tpl-home', 'home', '{brand} — {tagline}', '{brandDescription}'),
  ('tpl-generator', 'generator', 'Domain generator — brandable names from {root}', 'Generate brandable domain names from your root keyword with explained quality and brandability scores.'),
  ('tpl-industry', 'industry', '{industry} domain names — naming ideas and vocabulary', 'Domain naming ideas for {industry}: vocabulary, patterns and explainable scores from the DomainFits engine.'),
  ('tpl-blog-index', 'blog-index', 'Naming research and guides — {brand}', 'Practical writing on domain naming, brandability and availability data.'),
  ('tpl-post', 'post', '{title} — {brand}', '{excerpt}'),
  ('tpl-page', 'page', '{title} — {brand}', '{excerpt}'),
  ('tpl-tld', 'tld', '{tld} domain names — what you can verify', 'What we can and cannot verify about {tld} availability, and how to check it honestly.')
on conflict (id) do nothing;
`);

  // ---- navigation ---------------------------------------------------------
  // Generated from PRIMARY_NAV/FOOTER_NAV so the database seed and the code defaults are the
  // same menu. Once seeded, the database is authoritative — the defaults are only a fallback.
  const menuRows = [
    `  ('primary', 'Primary navigation', 'primary', 10)`,
    ...FOOTER_NAV.map((column, index) => {
      const id = `footer-${column.heading.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "")}`;
      return `  (${q(id)}, ${q(column.heading)}, 'footer', ${(index + 1) * 10})`;
    }),
  ].join(",\n");

  const itemRows = [
    ...PRIMARY_NAV.map((item, index) =>
      `  ('primary', ${q(item.label)}, ${q(item.href)}, ${q(item.description ?? "")}, ${(index + 1) * 10}, true)`,
    ),
    ...FOOTER_NAV.flatMap((column, columnIndex) => {
      const id = `footer-${column.heading.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "")}`;
      return column.items.map(
        (item, index) =>
          `  (${q(id)}, ${q(item.label)}, ${q(item.href)}, '', ${(index + 1) * 10 + columnIndex * 0}, true)`,
      );
    }),
  ].join(",\n");

  chunks.push(`
-- ---------------------------------------------------------------------------
-- Navigation
-- ---------------------------------------------------------------------------
insert into public.nav_menus (id, name, location, position) values
${menuRows}
on conflict (id) do update set
  name = excluded.name,
  location = excluded.location,
  position = excluded.position;

insert into public.nav_items (menu_id, label, href, description, position, enabled) values
${itemRows}
on conflict (menu_id, href) do update set
  label = excluded.label,
  description = excluded.description,
  position = excluded.position,
  enabled = excluded.enabled;
`);

  // ---- pages --------------------------------------------------------------
  chunks.push(`
-- ---------------------------------------------------------------------------
-- Static pages
-- ---------------------------------------------------------------------------
insert into public.pages (slug, title, excerpt, body, status, seo_title, meta_description, published_at) values
${DEFAULT_PAGES.map(
  (page) =>
    `  (${q(page.slug)}, ${q(page.title)}, ${q(page.excerpt)}, ${q(page.body)}, 'published', ${q(page.seoTitle)}, ${q(page.metaDescription)}, now())`,
).join(",\n")}
on conflict (slug) do nothing;
`);

  // ---- advertising defaults (disabled) -----------------------------------
  chunks.push(`
-- ---------------------------------------------------------------------------
-- Advertising: present but disabled and unconfigured. No publisher ID is invented.
-- ---------------------------------------------------------------------------
insert into public.ad_settings (id, provider, publisher_id, script_enabled, global_enabled, test_mode, consent_required) values
  ('global', 'none', null, false, false, true, true)
on conflict (id) do nothing;

insert into public.ad_slots (slot_key, template, placement, format, enabled, label, display_order) values
  ('home-after-intro', 'home', 'after-intro', 'horizontal', false, 'Advertisement', 10),
  ('generator-sidebar', 'generator', 'sidebar', 'vertical', false, 'Advertisement', 20),
  ('industry-after-intro', 'industry', 'after-intro', 'horizontal', false, 'Advertisement', 30),
  ('blog-index-mid', 'blog-index', 'mid-content', 'horizontal', false, 'Advertisement', 40),
  ('blog-post-mid', 'blog-post', 'mid-content', 'horizontal', false, 'Advertisement', 50),
  ('blog-post-end', 'blog-post', 'end-of-content', 'horizontal', false, 'Advertisement', 60),
  ('page-end', 'page', 'end-of-content', 'horizontal', false, 'Advertisement', 70)
on conflict (slot_key) do nothing;

insert into public.feature_flags (key, enabled, description) values
  ('public_api', false, 'Expose the versioned Edge Function API with API keys.'),
  ('ai_studio', false, 'Enable the AI content studio (requires a provider key).'),
  ('accounts', true, 'Allow user sign-up, saved names and collections.'),
  ('availability_checks', true, 'Enable availability lookups through the configured provider.'),
  ('advertising', false, 'Render advertising slots. Requires a publisher ID and consent.'),
  ('affiliate_routing', false, 'Route registrar clicks through configured affiliate providers.')
on conflict (key) do nothing;

commit;
`);

  return chunks.join("\n");
}


